<?php require __DIR__.'/bootstrap.php';
if ($_SERVER['REQUEST_METHOD']==='POST') { check_csrf(); $subject=trim($_POST['subject']??''); $grade=trim($_POST['grade']??''); $details=trim($_POST['details']??''); if ($subject!==''&&$grade!==''&&$details!=='') { $pdo->prepare('INSERT INTO requests (subject,grade,details) VALUES (?,?,?)')->execute([$subject,$grade,$details]); $sent=true; } }
$subjects=$pdo->query('SELECT DISTINCT subject FROM summaries WHERE published=1 ORDER BY subject')->fetchAll(PDO::FETCH_COLUMN);
$summaries=$pdo->query('SELECT id,title,subject,grade,description,file_name FROM summaries WHERE published=1 ORDER BY created_at DESC')->fetchAll();
?><!doctype html><html lang="he" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>מחברת פתוחה</title><link rel="stylesheet" href="style.css"></head><body><header><a class="brand" href="/">✦ מחברת פתוחה</a><nav><a href="#summaries">סיכומים</a><a href="#request">בקשי סיכום</a></nav></header><section class="hero"><div><p class="eyebrow">לומדים יחד, בחינם</p><h1>סיכומים טובים<br>פותחים דלתות.</h1><p>מאגר פתוח של סיכומים ברורים, בשביל הרגע שבו צריך לעשות סדר.</p><a class="button" href="#summaries">לכל הסיכומים</a></div><div class="hero-card">לומדים<br>יחד <b>✦</b></div></section><main><section id="summaries"><p class="eyebrow">המאגר</p><h2>מה בא לך ללמוד היום?</h2><div class="filters"><input id="search" placeholder="חפשי נושא או מקצוע..."><select id="subject"><option value="">כל המקצועות</option><?php foreach($subjects as $s): ?><option><?=e($s)?></option><?php endforeach ?></select></div><div class="cards" id="cards"><?php foreach($summaries as $s): ?><article data-subject="<?=e($s['subject'])?>" data-text="<?=e($s['title'].' '.$s['subject'].' '.$s['grade'])?>"><div class="cover">PDF <b><?=e($s['subject'])?></b></div><small><?=e($s['grade'])?></small><h3><?=e($s['title'])?></h3><p><?=e($s['description'])?></p><a href="uploads/<?=rawurlencode($s['file_name'])?>" target="_blank">לצפייה ולהורדה ←</a></article><?php endforeach ?></div></section><section id="request" class="request"><div><p class="eyebrow">חסר לך משהו?</p><h2>בקשי סיכום</h2><p>כתבי מה היית רוצה ללמוד. אין צורך בהרשמה או בפרטים אישיים.</p></div><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>מקצוע<input required name="subject"></label><label>שכבת לימוד<input required name="grade"></label><label>מה בדיוק צריך?<textarea required name="details" rows="4"></textarea></label><button class="button">שלחי בקשה</button><?php if(!empty($sent)): ?><p class="success">הבקשה נשלחה. תודה!</p><?php endif ?></form></section></main><footer>מחברת פתוחה · נבנה באהבה ללמידה</footer><script>const q=document.querySelector('#search'),s=document.querySelector('#subject');function f(){document.querySelectorAll('#cards article').forEach(x=>x.hidden=!x.dataset.text.includes(q.value)||!!(s.value&&x.dataset.subject!==s.value))}q.oninput=s.onchange=f</script></body></html>
